@inline function reei(::Type{BigFloat}, m::Integer, i::Integer, j::Integer, k::Integer)
    n = ((m * 2 + i) * 5 + j) * 27 + k + 1
    return BigFloat(@inbounds REEI_NUM[n])/BigFloat(@inbounds REEI_DEN[n])
end
